init.section:
vec3 sp = vec3(0.0);
vec3 dir = vec3(0.0, 0.0, 1.0);
dir = normalize(vec3(Rand(attributes.seed), Rand(attributes.seed), Rand(attributes.seed)) * 2.0 - 1.0 + 1e-5);
sp = dir * 0.6 * (1.0 - 1.0 * (1.0 - pow(Rand(attributes.seed), 1.0 / 3.0)));
vec3 worldDir = normalize((vec4(dir, 0.0) * i_v0).xyz + vec3(0.0, 0.0, 1e-6));
attributes.position = (vec4(sp, 1.0) * i_v0).xyz;
attributes.velocity = worldDir * 0.1 * 1.0;
attributes.lifetime = max(mix(1.7, 3.0, Rand(attributes.seed)), 0.0001);
attributes.startColor = vec4(1.0, 1.0, 1.0, 1.0);
attributes.startSize = vec3(mix(4.0, 6.0, Rand(attributes.seed)));
attributes.angle = vec3(0.0, 0.0, mix(0.0, 6.283185, Rand(attributes.seed)));
attributes.texStart = 0.0;
attributes.row = floor(Rand(attributes.seed) * 7.0);

update.section:
float dt = u_DeltaTime;
float t = clamp(attributes.age / attributes.lifetime, 0.0, 1.0);
float ageBefore = attributes.age;
attributes.position += (attributes.velocity + vec3(0.0)) * dt;
attributes.age += dt;
if (attributes.age >= attributes.lifetime) attributes.alive = false;

output.section:
float t = clamp(attributes.age / max(attributes.lifetime, 1e-4), 0.0, 1.0);
vec4 c = attributes.startColor;
attributes.color = c.rgb;
attributes.alpha = c.a;
vec3 s = attributes.startSize;
s *= (1.0 * SampleCurve(o_v0, t));
attributes.size3 = s * 1.0;
float fr = fract(attributes.texStart + (0.9999 * SampleCurve(o_v1, t)) * 1.0) * 84.0;
attributes.frame = fr;

material.code:
vec4 shadeFragment() {
  vec4 col = 2.0 * vColor * texture(mMainTex, vTex0.xy * mMainTex_ST.xy + mMainTex_ST.zw);
  float gray = dot(col.rgb, vec3(0.3));
  col.rgb *= gray * mTintColor.rgb;
  col.rgb += 3.0 * col.rgb; // the shader's linear-colour-space boost
  col.a = clamp(col.a * mTintColor.a, 0.0, 1.0);
  return col;
}

